const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const bool = (v) => ({ t: 'b', v })
const txt = (v) => ({ t: 's', v })
const ZERO = num(0)

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) fail('error: usage: cli.js values|deps')
const mode = args[0]

// ---- addresses
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = m[1].toUpperCase()
  const ci = col.length === 1 ? col.charCodeAt(0) - 64 : 26 * (col.charCodeAt(0) - 64) + col.charCodeAt(1) - 64
  return { col, ci, row, key: col + row }
