  return ci <= 26 ? String.fromCharCode(64 + ci) : String.fromCharCode(64 + Math.floor((ci - 1) / 26)) + String.fromCharCode(65 + ((ci - 1) % 26))
}
function rangeCells(a, b) {
  const out = []
  const c0 = Math.min(a.ci, b.ci), c1 = Math.max(a.ci, b.ci)
  const r0 = Math.min(a.row, b.row), r1 = Math.max(a.row, b.row)
  for (let c = c0; c <= c1; c++) for (let r = r0; r <= r1; r++) out.push({ ci: c, row: r, key: colName(c) + r })
  return out
}

// ---- input
const text = fs.readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
  const word = m[1]
  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { addr: a, content: m[2] })
})

// ---- formula parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=)/.exec(s.slice(i)))) { toks.push({ k: 'op', v: m[0] }); i += 2; continue }
