  const toks = tokenize(body)
  let p = 0
  const peek = () => toks[p]
  const isOp = (...ops) => peek() && peek().k === 'op' && ops.includes(peek().v)
  function expr() {
    let l = add()
    while (isOp('=', '<>', '<', '<=', '>', '>=')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: add() } }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+', '-')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*', '/')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-', '+')) { const op = toks[p++].v; return { k: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p++]
    if (!t) throw new Error('eof')
    if (t.k === 'num') return { k: 'num', v: t.v }
    if (t.k === '(') {
      const e = expr()
      if (!peek() || peek().k !== ')') throw new Error('paren')
      p++
      return { k: 'paren', e }
    }
    if (t.k === 'word') {
      if (peek() && peek().k === '(') {
        p++
        const args = []
        if (peek() && peek().k === ')') p++
        else {
          for (;;) {
            args.push(expr())
            const n = toks[p++]
            if (!n) throw new Error('call')
            if (n.k === ')') break
            if (n.k !== ',') throw new Error('call')
          }
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (peek() && peek().k === ':') {
        p++
        const t2 = toks[p++]
        if (!t2 || t2.k !== 'word' || up === 'TRUE' || up === 'FALSE') throw new Error('range')
