  switch (n.k) {
    case 'ref': { const a = parseAddr(n.name); if (a) set.set(a.key, a); break }
    case 'range': {
      const a = parseAddr(n.a), b = parseAddr(n.b)
      if (a && b) for (const c of rangeCells(a, b)) set.set(c.key, c)
      break
    }
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'un': case 'paren': collectDeps(n.e, set); break
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
