      const set = new Map()
      collectDeps(c.ast, set)
      for (const a of [...set.values()].sort(cmpAddr)) out += ' ' + a.key
    }
    out += '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---- evaluation
const memo = new Map()
const active = new Set()

function literal(s) {
  if (s === '') return ZERO
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRORS.includes(s)) return err(s)
  return txt(s)
}

function cellValue(key) {
  const c = cells.get(key)
  if (!c) return ZERO
  if (memo.has(key)) return memo.get(key)
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  if (c.content[0] !== '=') v = literal(c.content)
  else if (c.bad || misplacedRange(c.ast, false)) v = err('#ERR!')
  else v = evalNode(c.ast)
  active.delete(key)
  memo.set(key, v)
  return v
}

