const kindRank = { n: 0, s: 1, b: 2 }

function compare(a, b) {
  if (a.t !== b.t) return kindRank[a.t] - kindRank[b.t]
  if (a.t === 's') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  const x = a.t === 'b' ? Number(a.v) : a.v
