  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
  if (name === 'AVG') return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
  if (name === 'MIN') return num(nums.reduce((s, x) => Math.min(s, x)))
  return num(nums.reduce((s, x) => Math.max(s, x)))
}

function evalNode(n) {
  switch (n.k) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'paren': return evalNode(n.e)
    case 'range': return err('#ERR!')
    case 'ref': {
      const a = parseAddr(n.name)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.t === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'call': return evalCall(n)
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l.t === 'e') return l
      if (r.t === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        switch (n.op) {
          case '=': return bool(c === 0)
          case '<>': return bool(c !== 0)
          case '<': return bool(c < 0)
          case '<=': return bool(c <= 0)
          case '>': return bool(c > 0)
          default: return bool(c >= 0)
        }
      }
      const a = toNum(l)
      if (a.t === 'e') return a
      const b = toNum(r)
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        default: return finite(Math.pow(a.v, b.v))
      }
    }
  }
  return err('#ERR!')
}

function show(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const sorted = [...cells.values()].sort((x, y) => cmpAddr(x.addr, y.addr))
let out = ''
for (const c of sorted) out += `${c.addr.key}=${show(cellValue(c.addr.key))}\n`
process.stdout.write(out)
"}

