      }
      const up = t.v.toUpperCase()
      if (peek() && peek().k === ':') {
        p++
        const t2 = toks[p++]
        if (!t2 || t2.k !== 'word' || up === 'TRUE' || up === 'FALSE') throw new Error('range')
        const u2 = t2.v.toUpperCase()
        if (u2 === 'TRUE' || u2 === 'FALSE' || (peek() && peek().k === '(')) throw new Error('range')
        return { k: 'range', a: up, b: u2 }
      }
      if (up === 'TRUE') return { k: 'bool', v: true }
      if (up === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', name: up }
    }
    throw new Error('unexpected')
  }
  const e = expr()
  if (p !== toks.length) throw new Error('trailing')
  return e
}

function misplacedRange(n, direct) {
  switch (n.k) {
    case 'range': return !direct
    case 'bin': return misplacedRange(n.l, false) || misplacedRange(n.r, false)
    case 'un': case 'paren': return misplacedRange(n.e, false)
    case 'call': return n.args.some((a) => misplacedRange(a, true))
    default: return false
  }
}

function collectDeps(n, set) {
  switch (n.k) {
    case 'ref': { const a = parseAddr(n.name); if (a) set.set(a.key, a); break }
    case 'range': {
      const a = parseAddr(n.a), b = parseAddr(n.b)
      if (a && b) for (const c of rangeCells(a, b)) set.set(c.key, c)
      break
    }
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'un': case 'paren': collectDeps(n.e, set); break
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
  }
}

// parse every cell
for (const c of cells.values()) {
  c.ast = null
  if (c.content[0] === '=') {
    try { c.ast = parseFormula(c.content.slice(1)) } catch { c.ast = null; c.bad = true }
  }
}

if (mode === 'deps') {
  const sorted = [...cells.values()].sort((x, y) => cmpAddr(x.addr, y.addr))
  let out = ''
  for (const c of sorted) {
    out += c.addr.key + ':'
    if (c.ast) {
      const set = new Map()
      collectDeps(c.ast, set)
      for (const a of [...set.values()].sort(cmpAddr)) out += ' ' + a.key
    }
    out += '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---- evaluation
const memo = new Map()
const active = new Set()

function literal(s) {
  if (s === '') return ZERO
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRORS.includes(s)) return err(s)
  return txt(s)
}

function cellValue(key) {
  const c = cells.get(key)
  if (!c) return ZERO
  if (memo.has(key)) return memo.get(key)
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  if (c.content[0] !== '=') v = literal(c.content)
  else if (c.bad || misplacedRange(c.ast, false)) v = err('#ERR!')
  else v = evalNode(c.ast)
  active.delete(key)
  memo.set(key, v)
  return v
}

function toNum(v) {
  if (v.t === 'e') return v
  if (v.t === 's') return err('#VALUE!')
  if (v.t === 'b') return num(v.v ? 1 : 0)
  return v
}
function finite(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }
const kindRank = { n: 0, s: 1, b: 2 }

function compare(a, b) {
  if (a.t !== b.t) return kindRank[a.t] - kindRank[b.t]
  if (a.t === 's') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  const x = a.t === 'b' ? Number(a.v) : a.v
  const y = b.t === 'b' ? Number(b.v) : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function argValues(a) {
  if (a.k === 'range') {
    const x = parseAddr(a.a), y = parseAddr(a.b)
    if (!x || !y) return [err('#REF!')]
    return rangeCells(x, y).map((c) => cellValue(c.key))
  }
  return [evalNode(a)]
}

function evalCall(n) {
  const name = n.name
  const aggs = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
  if (name === 'IF') {
    if (n.args.length !== 3) return err('#ERR!')
    const c = evalNode(n.args[0])
    if (c.t === 'e') return c
    if (c.t === 's') return err('#VALUE!')
    const truth = c.t === 'b' ? c.v : c.v !== 0
    return evalNode(n.args[truth ? 1 : 2])
  }
  if (name === 'ABS') {
    if (n.args.length !== 1) return err('#ERR!')
    const v = toNum(evalNode(n.args[0]))
    return v.t === 'e' ? v : num(Math.abs(v.v))
  }
  if (!aggs.includes(name)) return err('#NAME?')
  if (n.args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of n.args) vals.push(...argValues(a))
  const e = vals.find((v) => v.t === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
  if (name === 'AVG') return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
  if (name === 'MIN') return num(nums.reduce((s, x) => Math.min(s, x)))
  return num(nums.reduce((s, x) => Math.max(s, x)))
}

function evalNode(n) {
  switch (n.k) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'paren': return evalNode(n.e)
    case 'range': return err('#ERR!')
    case 'ref': {
      const a = parseAddr(n.name)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.t === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'call': return evalCall(n)
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l.t === 'e') return l
      if (r.t === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        switch (n.op) {
          case '=': return bool(c === 0)
          case '<>': return bool(c !== 0)
          case '<': return bool(c < 0)
          case '<=': return bool(c <= 0)
          case '>': return bool(c > 0)
          default: return bool(c >= 0)
        }
      }
      const a = toNum(l)
      if (a.t === 'e') return a
      const b = toNum(r)
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        default: return finite(Math.pow(a.v, b.v))
      }
    }
  }
  return err('#ERR!')
}

function show(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const sorted = [...cells.values()].sort((x, y) => cmpAddr(x.addr, y.addr))
let out = ''
for (const c of sorted) out += `${c.addr.key}=${show(cellValue(c.addr.key))}\n`
process.stdout.write(out)
